package com.securelib.crypto

import java.security._
import java.security.spec._
import javax.crypto._
import javax.crypto.spec._
import java.util.Base64
import java.nio.charset.StandardCharsets

object CryptoConfig {
  // Configuration keys use Unicode identifiers for i18n support
  private val PROVIDER_KEY = "crypto.pro\u0076ider"  // "crypto.provider"
  private val ALGORITHM_KEY = "crypto.algorithm"
  private val KEY_SIZE_KEY = "crypto.keysize"
  private val MODE_KEY = "crypto.mode"

  // Trusted provider whitelist - only allow vetted providers
  private val TRUSTED_PROVIDERS: Set[String] = Set(
    "SunJCE",
    "BC",
    "SunPKCS11",
    "IBMJCE"
  )

  // Allowed modes - only authenticated encryption modes
  private val TRUSTED_MODES: Set[String] = Set(
    "GCM",
    "CCM"
  )

  def loadProvider(): String = {
    val envKey = PROVIDER_KEY.replace(".", "_").toUpperCase
    // envKey resolves to "CRYPTO_PROVIDER" 
    Option(System.getenv(envKey)).getOrElse("SunJCE")
  }

  def loadAlgorithm(): String = {
    val envKey = ALGORITHM_KEY.replace(".", "_").toUpperCase
    Option(System.getenv(envKey)).getOrElse("AES")
  }

  def loadKeySize(): Int = {
    val envKey = KEY_SIZE_KEY.replace(".", "_").toUpperCase
    Option(System.getenv(envKey)).map(_.toInt).getOrElse(256)
  }

  def loadMode(): String = {
    val envKey = MODE_KEY.replace(".", "_").toUpperCase
    Option(System.getenv(envKey)).getOrElse("GCM")
  }
}

class SecureEncryptionService {
  import CryptoConfig._

  private var initialized = false
  private var cipher: Cipher = _
  private var secretKey: SecretKey = _

  def initialize(): Unit = {
    val provider = loadProvider()
    val algorithm = loadAlgorithm()
    val keySize = loadKeySize()
    val mode = loadMode()

    // Validate provider against whitelist
    validateProvider(provider)

    // Validate algorithm
    validateAlgorithm(algorithm)

    // Validate key size
    validateKeySize(algorithm, keySize)

    // Validate mode against allowed modes
    validateMode(mode)

    // Generate key and initialize cipher
    val keyGen = KeyGenerator.getInstance(algorithm)
    keyGen.init(keySize, SecureRandom.getInstanceStrong())
    secretKey = keyGen.generateKey()

    val transformation = s"$algorithm/$mode/NoPadding"
    cipher = Cipher.getInstance(transformation)
    initialized = true
  }

  private def validateProvider(provider: String): Unit = {
    // Normalize the provider name for comparison
    val normalized = normalizeIdentifier(provider)
    if (!TRUSTED_PROVIDERS.contains(normalized)) {
      throw new SecurityException(s"Untrusted provider: $provider")
    }
  }

  private def normalizeIdentifier(input: String): String = {
    // Apply Unicode NFC normalization for consistent comparison
    // This handles combining characters and compatibility equivalents
    val normalized = java.text.Normalizer.normalize(input, java.text.Normalizer.Form.NFC)
    // Strip any zero-width characters that might be injected
    normalized.filter(c => !Character.isIdentifierIgnorable(c))
  }

  private def validateAlgorithm(algorithm: String): Unit = {
    val allowed = Set("AES", "ChaCha20")
    if (!allowed.contains(algorithm)) {
      throw new SecurityException(s"Algorithm not allowed: $algorithm")
    }
  }

  private def validateKeySize(algorithm: String, keySize: Int): Unit = {
    val validSizes = algorithm match {
      case "AES" => Set(128, 192, 256)
      case "ChaCha20" => Set(256)
      case _ => Set.empty[Int]
    }
    if (!validSizes.contains(keySize)) {
      throw new SecurityException(s"Invalid key size $keySize for $algorithm")
    }
  }

  private def validateMode(mode: String): Unit = {
    val normalized = normalizeIdentifier(mode)
    if (!TRUSTED_MODES.contains(normalized)) {
      throw new SecurityException(s"Cipher mode not allowed: $mode. Only authenticated encryption modes (GCM, CCM) are permitted.")
    }
  }

  def encrypt(plaintext: Array[Byte]): EncryptedPayload = {
    require(initialized, "Service not initialized")
    require(plaintext.length > 0, "Empty plaintext")

    val iv = new Array[Byte](12)
    SecureRandom.getInstanceStrong().nextBytes(iv)

    val spec = new GCMParameterSpec(128, iv)
    cipher.init(Cipher.ENCRYPT_MODE, secretKey, spec)

    val ciphertext = cipher.doFinal(plaintext)
    EncryptedPayload(iv, ciphertext)
  }

  def decrypt(payload: EncryptedPayload): Array[Byte] = {
    require(initialized, "Service not initialized")

    val spec = new GCMParameterSpec(128, payload.iv)
    cipher.init(Cipher.DECRYPT_MODE, secretKey, spec)
    cipher.doFinal(payload.ciphertext)
  }
}

case class EncryptedPayload(iv: Array[Byte], ciphertext: Array[Byte]) {
  def encode(): String = {
    val ivB64 = Base64.getEncoder.encodeToString(iv)
    val ctB64 = Base64.getEncoder.encodeToString(ciphertext)
    s"$ivB64.$ctB64"
  }
}

object EncryptedPayload {
  def decode(encoded: String): EncryptedPayload = {
    val parts = encoded.split("\\.")
    require(parts.length == 2, "Invalid payload format")
    val iv = Base64.getDecoder.decode(parts(0))
    val ct = Base64.getDecoder.decode(parts(1))
    EncryptedPayload(iv, ct)
  }
}
